17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.ArrayList;
24	import java.util.Collection;
25	import java.util.List;
26	import java.util.Locale;
27	import java.util.regex.Pattern;
28	
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
40	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
68	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
69	     */
70	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        validateRequiredOwnerFields(ownerFieldsDto);
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
122	        owner.setTelephone(normalizedTelephone);
123	        owner.setEmail(normalizeEmail(owner.getEmail()));
124	        if (owner.getRegistrationDate() == null) {
125	            owner.setRegistrationDate(LocalDate.now());
126	        }
127	        rejectDuplicateTelephone(normalizedTelephone);
128	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
129	            assignHousehold(owner);
130	        } else {
131	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
132	        }
133	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
134	        this.clinicService.saveOwner(owner);
135	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
136	        headers.setLocation(UriComponentsBuilder.newInstance()
137	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
138	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
144	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
145	        if (currentOwner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        currentOwner.setAddress(ownerFieldsDto.getAddress());
149	        currentOwner.setCity(ownerFieldsDto.getCity());
150	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
151	        currentOwner.setLastName(ownerFieldsDto.getLastName());
152	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
153	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
154	        this.clinicService.saveOwner(currentOwner);
155	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Transactional
160	    @Override
161	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        this.clinicService.deleteOwner(owner);
167	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        HttpHeaders headers = new HttpHeaders();
178	        Pet pet = petMapper.toPet(petFieldsDto);
179	        owner.setId(ownerId);
180	        pet.setOwner(owner);
181	        pet.getType().setName(null);
182	        this.clinicService.savePet(pet);
183	        PetDto petDto = petMapper.toPetDto(pet);
184	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
185	            .buildAndExpand(pet.getId()).toUri());
186	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
192	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
193	        if (currentOwner != null) {
194	            Pet currentPet = this.clinicService.findPetById(petId);
195	            if (currentPet != null) {
196	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
197	                currentPet.setName(petFieldsDto.getName());
198	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
199	                this.clinicService.savePet(currentPet);
200	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	            }
202	        }
203	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
209	        HttpHeaders headers = new HttpHeaders();
210	        Visit visit = visitMapper.toVisit(visitFieldsDto);
211	        Pet pet = new Pet();
212	        pet.setId(petId);
213	        visit.setPet(pet);
214	        this.clinicService.saveVisit(visit);
215	        VisitDto visitDto = visitMapper.toVisitDto(visit);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
217	            .buildAndExpand(visit.getId()).toUri());
218	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
219	    }
220	
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner != null) {
227	            Pet pet = owner.getPet(petId);
228	            if (pet != null) {
229	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    /**
236	     * Builds the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'} where
237	     * {@code LAST3} is the upper-cased first three letters of the owner's last name and {@code NNNN}
238	     * is a global 4-digit zero-padded sequence equal to one more than the current number of owners.
239	     * For example an owner named "Smithers" created when 10 owners already exist gets {@code 'SMI-0011'}.
240	     *
241	     * @param lastName the owner's last name
242	     * @return the assigned customer code
243	     */
244	    private String nextCustomerCode(String lastName) {
245	        String letters = lastName == null ? "" : lastName;
246	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
247	        int sequence = this.clinicService.findAllOwners().size() + 1;
248	        return String.format("%s-%04d", last3, sequence);
249	    }
250	
251	    /**
252	     * Rejects an owner payload that is missing or blank in any of the required fields
253	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
254	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
255	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
256	     * guard enforces the rule uniformly for every required field.
257	     *
258	     * @param ownerFieldsDto the submitted owner payload
259	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
260	     */
261	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
262	        List<String> invalidFields = new ArrayList<>();
263	        if (isBlank(ownerFieldsDto.getFirstName())) {
264	            invalidFields.add("firstName");
265	        }
266	        if (isBlank(ownerFieldsDto.getLastName())) {
267	            invalidFields.add("lastName");
268	        }
269	        if (isBlank(ownerFieldsDto.getAddress())) {
270	            invalidFields.add("address");
271	        }
272	        if (isBlank(ownerFieldsDto.getCity())) {
273	            invalidFields.add("city");
274	        }
275	        if (isBlank(ownerFieldsDto.getTelephone())) {
276	            invalidFields.add("telephone");
277	        }
278	        if (!invalidFields.isEmpty()) {
279	            throw new InvalidOwnerFieldsException(invalidFields);
280	        }
281	    }
282	
283	    private boolean isBlank(String value) {
284	        return value == null || value.isBlank();
285	    }
286	
287	    /**
288	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
289	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
290	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
291	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
292	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
293	     *
294	     * @param telephone the raw telephone value from the submitted owner payload
295	     * @return the normalized E.164 telephone number
296	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
297	     */
298	    private String normalizeTelephone(String telephone) {
299	        String raw = telephone == null ? "" : telephone.strip();
300	        boolean hasCountryCode = raw.startsWith("+");
301	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
302	        String digits;
303	        if (hasCountryCode) {
304	            digits = cleaned.substring(1);
305	        } else {
306	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
307	            digits = "61" + national;
308	        }
309	        if (!digits.matches("[0-9]{8,15}")) {
310	            throw new InvalidOwnerFieldsException(List.of("telephone"));
311	        }
312	        return "+" + digits;
313	    }
314	
315	    /**
316	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
317	     * returning {@code null} when the value cannot form a valid E.164 number.
318	     *
319	     * @param telephone an existing owner's stored telephone value
320	     * @return the E.164 form, or {@code null} if it cannot be normalized
321	     */
322	    private String toE164OrNull(String telephone) {
323	        try {
324	            return normalizeTelephone(telephone);
325	        } catch (InvalidOwnerFieldsException ex) {
326	            return null;
327	        }
328	    }
329	
330	    /**
331	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
332	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
333	     * accepted value is trimmed and lower-cased before it is stored and returned.
334	     *
335	     * @param email the raw email value from the submitted owner payload, may be {@code null}
336	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
337	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
338	     */
339	    private String normalizeEmail(String email) {
340	        if (email == null) {
341	            return null;
342	        }
343	        String trimmed = email.strip();
344	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
345	            throw new InvalidOwnerFieldsException(List.of("email"));
346	        }
347	        return trimmed.toLowerCase(Locale.ROOT);
348	    }
349	
350	    /**
351	     * Rejects creating an owner whose E.164 telephone is already used by any other owner.
352	     * Existing owners' telephones are converted to E.164 form before comparison so that
353	     * differently-formatted representations of the same number are treated as duplicates.
354	     *
355	     * @param normalizedTelephone the E.164 telephone of the owner being created
356	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same E.164 telephone
357	     */
358	    private void rejectDuplicateTelephone(String normalizedTelephone) {
359	        boolean duplicate = this.clinicService.findAllOwners().stream()
360	            .map(Owner::getTelephone)
361	            .filter(telephone -> telephone != null)
362	            .map(this::toE164OrNull)
363	            .filter(telephone -> telephone != null)
364	            .anyMatch(normalizedTelephone::equals);
365	        if (duplicate) {
366	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
367	        }
368	    }
369	
370	    /**
371	     * Rejects creating an owner whose last name and address both match an existing owner. Both fields
372	     * are compared case-insensitively with surrounding and repeated internal whitespace collapsed, so
373	     * that e.g. {@code "  110  W. Liberty  St. "} and {@code "110 w. liberty st."} are treated as the
374	     * same address. This guard is bypassed for a request that sets {@code sharesHousehold} true.
375	     *
376	     * @param lastName the last name of the owner being created
377	     * @param address the address of the owner being created
378	     * @throws DuplicateOwnerHouseholdException if another owner shares the same last name and address
379	     */
380	    private void rejectDuplicateHousehold(String lastName, String address) {
381	        String normalizedLastName = normalizeForComparison(lastName);
382	        String normalizedAddress = normalizeForComparison(address);
383	        boolean duplicate = this.clinicService.findAllOwners().stream()
384	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
385	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
386	        if (duplicate) {
387	            throw new DuplicateOwnerHouseholdException(lastName, address);
388	        }
389	    }
390	
391	    /**
392	     * Assigns the owner being created a household identifier when the request opts into sharing a
393	     * household. The identifier is a stable value derived from the owner's normalized last name and
394	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
395	     * value regardless of creation order. Any already-existing owner in the same household that has no
396	     * identifier yet is back-filled with the same value so the whole household stays consistent.
397	     *
398	     * @param owner the owner being created, whose household id is set in place
399	     */
400	    private void assignHousehold(Owner owner) {
401	        String householdId = householdId(owner.getLastName(), owner.getAddress());
402	        String normalizedLastName = normalizeForComparison(owner.getLastName());
403	        String normalizedAddress = normalizeForComparison(owner.getAddress());
404	        for (Owner existing : this.clinicService.findAllOwners()) {
405	            if (existing.getHouseholdId() == null
406	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
407	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress()))) {
408	                existing.setHouseholdId(householdId);
409	                this.clinicService.saveOwner(existing);
410	            }
411	        }
412	        owner.setHouseholdId(householdId);
413	    }
414	
415	    /**
416	     * Derives the stable household identifier for a given last name and address. The value is
417	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
418	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
419	     * the same household therefore always produce the same identifier.
420	     *
421	     * @param lastName the owner's last name
422	     * @param address the owner's address
423	     * @return the stable household identifier
424	     */
425	    private String householdId(String lastName, String address) {
426	        String key = normalizeForComparison(lastName) + "\n" + normalizeForComparison(address);
427	        try {
428	            byte[] digest = MessageDigest.getInstance("SHA-256")
429	                .digest(key.getBytes(StandardCharsets.UTF_8));
430	            StringBuilder hex = new StringBuilder();
431	            for (int i = 0; i < 6; i++) {
432	                hex.append(String.format("%02X", digest[i]));
433	            }
434	            return "HH-" + hex;
435	        } catch (NoSuchAlgorithmException ex) {
436	            throw new IllegalStateException("SHA-256 not available", ex);
437	        }
438	    }
439	
440	    /**
441	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
442	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
443	     * result is lower-cased. A {@code null} value normalizes to the empty string.
444	     *
445	     * @param value the value to normalize, may be {@code null}
446	     * @return the normalized value
447	     */
448	    private String normalizeForComparison(String value) {
449	        if (value == null) {
450	            return "";
451	        }
452	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
453	    }
454	}
